export const STRING_CORE_SPECIES = 2424

export interface StringSpecies {
  taxon: number
  name: string
  core: boolean
}

let parsed: StringSpecies[] | null = null

// Every organism in STRING, parsed on first use.
export function stringSpecies(): StringSpecies[] {
  if (!parsed) {
    parsed = SPECIES_TEXT.split('\n').map((line, i) => {
      const tab = line.indexOf('\t')
      return {
        taxon: Number(line.slice(0, tab)),
        name: line.slice(tab + 1),
        core: i < STRING_CORE_SPECIES,
      }
    })
  }
  return parsed
}

export function stringSpeciesName(taxon: string | number): string | null {
  const t = Number(taxon)
  const hit = stringSpecies().find((s) => s.taxon === t)
  return hit ? hit.name : null
}
